def measured_results(path):
 if path is None:return ''
 report=json.loads(path.read_text())
 if report.get('families')!=14 or report.get('cases_per_model')!=168 or not report.get('schema_constrained_decoding'):
  raise ValueError('Unexpected completed model sample protocol')
 rows=[]
 for row in report['rows']:
  def pct(key):return f"{100*row[key]:.1f}%"
  rows.append('<tr><th scope="row">'+html.escape(row['model'])+'</th><td>'+pct('decision_exact')+'</td><td>'+pct('amount_exact')+'</td><td>'+pct('core_exact')+'</td></tr>')
 return '''<section class="wrap measured" id="results"><div class="eyebrow">MEASURED LOCAL RUNS</div><h2>What do language models get right?</h2><p>Actual outputs on 14 preselected test families: 168 related views per model. Both models used the same fixed JSON-schema constrained decoding. Core exact requires the decision, nominal contract amount and full issue set together.</p><div class="results-scroll"><table><thead><tr><th>Local model</th><th>Decision exact</th><th>Amount exact</th><th>Core exact</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table></div><p class="small">This small synthetic sample has 14 family clusters, not 168 independent observations. These are diagnostic results, not a model ranking or production accuracy estimate. <a href="https://huggingface.co/datasets/Bayanat-Labs/arabic-reconciliation-bench/blob/main/RESULTS.md">Read the full protocol, cluster intervals, evidence and paired results ↗</a></p></section>'''

def main():
 p=argparse.ArgumentParser();p.add_argument('--release-dir',type=Path,required=True);p.add_argument('--output-dir',type=Path,required=True);p.add_argument('--model-results',type=Path);args=p.parse_args();r=args.release_dir;o=args.output_dir;o.mkdir(parents=True,exist_ok=True)
 chosen={}
 for path in (r/'data/cases').glob('test-*.parquet'):
  for batch in pq.ParquetFile(path).iter_batches(columns=['family_id','mechanism','world','view']):
   for row in batch.to_pylist():
    rank=hashlib.sha256(('arb-visual-v1:'+row['family_id']).encode()).hexdigest();key=row['mechanism']
    if key not in chosen or rank<chosen[key][0]:chosen[key]=(rank,row['family_id'])
 families={m:{'family_id':v[1],'label_en':MECHANISM_EN[m],'label_ar':MECHANISM_AR[m],'cases':{}} for m,v in chosen.items()};wanted={v[1] for v in chosen.values()};cases={}
 for path in (r/'data/cases').glob('test-*.parquet'):
  for batch in pq.ParquetFile(path).iter_batches():
   for row in batch.to_pylist():
    if row['family_id'] in wanted:cases[row['case_id']]=row
 with gzip.open(r/'specs/test.jsonl.gz','rt') as f:
  for line in f:
   spec=json.loads(line)
   if spec['case_id'] in cases:
    row=cases[spec['case_id']];row['edit']=spec['edit'];row['trace']=spec['gold']['trace'];families[row['mechanism']]['cases'][row['world']+'/'+row['view']]=row
 if len(families)!=14 or any(len(x['cases'])!=12 for x in families.values()):raise ValueError('Incomplete demo families')
 for row in cases.values():
  visible={field for d in row['documents'] for field in __import__('re').findall(r'\[([^\]]+)\]',d['text'])}
  if not set(row['gold_evidence_ids'])<=visible:raise ValueError('Invalid reference evidence in demo')
 payload=json.dumps({'families':families},ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('\u2028','\\u2028').replace('\u2029','\\u2029')
 rendered=HTML.replace('__PAYLOAD__',payload)
